const x=$json||{};
const action=String(x.action_id||'').trim(); const status=String(x.status||'').trim();
if(!action||!['accepted','executing','succeeded','failed'].includes(status)) throw new Error('Invalid VIRYA OS receipt');
const executor=String($env.VIRYAOS_EXECUTOR_ID||'virya-n8n-primary').trim(); const claim=x.claim_token?String(x.claim_token).trim():null;
const key=`${action}:${executor}:${status}:${claim||'legacy'}`;
const body={receipt_key:key,executor_id:executor,status,claim_token:claim,provider_reference:x.provider_reference?String(x.provider_reference).slice(0,240):null,error_kind:status==='failed'?String(x.error_kind||'provider_failed').slice(0,96):null,metadata:(x.metadata&&typeof x.metadata==='object')?x.metadata:{},occurred_at:String(x.occurred_at||new Date().toISOString()),action_id:action};
const store=$getWorkflowStaticData('global'); store.pending_receipts=store.pending_receipts||{}; store.pending_receipts[key]=body;
const entries=Object.entries(store.pending_receipts).sort((a,b)=>String(b[1]?.occurred_at||'').localeCompare(String(a[1]?.occurred_at||'')));
if(entries.length>1000) store.pending_receipts=Object.fromEntries(entries.slice(0,1000));
return [{json:body}];

const action=String($json.action_id||'').trim(); const status=String($json.status||'').trim();
if(action&&status){
  const store=$getWorkflowStaticData('global'); store.pending_receipts=store.pending_receipts||{};
  for(const [key,receipt] of Object.entries(store.pending_receipts)){
    if(String(receipt?.action_id||'')===action&&String(receipt?.status||'')===status) delete store.pending_receipts[key];
  }
}
return [{json:{receipt_delivered:true,action_id:action,status}}];
